ientExcessSingle:500,outpatientExcessFamily:1500,outpatientExcessNote:"100% of actual charges once the outpatient out-of-pocket exceeds EUR 1,500 per family per calendar year, or EUR 500 for a single insured. The out-of-pocket is calculated against UCR, not against what was actually charged.",gpAndSpecialistPct:90,gpAndSpecialistBasis:"90% of charges within UCR limits, excluding dentists",cancerSpecialistConsultations:"100% of charges, not subject to UCR limits, for treatment starting from 1 April 2024",paramedicalServices:"100% of charges, if more than 5 sessions - nurses, physiotherapists, speech therapists, orthoptists, podiatrists",laboratoryTests:"100% of charges",technicalTreatmentsXrayUltrasound:"100% of charges",prescriptionDrugs:"100% of charges, including compulsory or medically recommended vaccinations",dentalCareLimit:2e3,dentalCareBasis:"Dentist fees, preventive and surgical dental care and radiology, per beneficiary per calendar year",dentalImplantsLimitZone1:2400,dentalImplantsLimitZone234:1200,dentalImplantsPerProsthesisCapZone1:800,orthodonticsLimitZone1:1e4,orthodonticsLimitZone2:8e3,orthodonticsLimitZone34:5e3,orthodonticsBasis:"Children under 26, per child during the policy lifetime",visionGlassesLensesLimit:750,laserEyeSurgeryLimitPerEye:1e3,laserEyeSurgeryBasis:"One procedure per eye per beneficiary during the policy lifetime; once done, glasses and lenses are not reimbursed without prior approval",maternityNaturalChildbirthZone1:15e3,maternityNaturalChildbirthZone2:12e3,maternityNaturalChildbirthZone3:1e4,maternityNaturalChildbirthZone4:7e3,ivfLimit:6e3,ivfMaxAttempts:4,medicalProsthesesLimit:1e3,medicalProsthesesBasis:"Hearing aids, orthopaedic and similar, excluding dental prostheses, per beneficiary per calendar year, aggregate",alternativeMedicineLimit:500,alternativeMedicineBasis:"Acupuncture, osteopathy and chiropractic, aggregate, per beneficiary per calendar year",psychotherapySessionsPerYear:15,psychotherapyPerSessionLimit:300,expatri